#!/usr/bin/env bash
# wget install — profile ui. Generated by vibed-infra package.
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]:-$0}")" && pwd)"
PACKAGER_RAW="${PACKAGER_RAW:-https://raw.githubusercontent.com/naiemk/vibed-infra/main}"
export PACKAGER_RAW
export PRODUCT_RAW="${PRODUCT_RAW:-https://raw.githubusercontent.com/naiemk/onchain-invoice/main/deploy/tcmain/dist}"
export PACKAGECONFIG_URL="${PACKAGECONFIG_URL:-https://raw.githubusercontent.com/naiemk/onchain-invoice/main/deploy/tcmain/dist/packageconfig.yaml}"
export INFRA_PROFILE=ui
export INSTALL_DIR="${INSTALL_DIR:-.}"
if [[ "$PACKAGER_RAW" =~ ^/ ]]; then
  exec bash "$PACKAGER_RAW/install.sh" --profile ui
fi
if command -v curl >/dev/null 2>&1; then
  exec bash <(curl -fsSL "${PACKAGER_RAW}/install.sh") --profile ui
else
  exec bash <(wget -qO- "${PACKAGER_RAW}/install.sh") --profile ui
fi
